195|const buildUsersWhere = (query: UsersListQuery): Prisma.BaseUserWhereInput => {
196|  const provider = readControlPlaneProvider();
197|  const and: Prisma.BaseUserWhereInput[] = [];
198|
199|  if (query.email?.trim()) {
