225|      },
226|    });
227|  }
228|
229|  if (query.roleNames?.trim()) {
230|    const roleNames = query.roleNames
231|      .split(',')
232|      .map((role) => role.trim().toUpperCase())
233|      .filter(Boolean);
234|    if (roleNames.length > 0) {
235|      and.push({
236|        userRoles: {
