238|        },
239|      });
240|    }
241|  }
242|
243|  if (query.search?.trim()) {
244|    const needle = query.search.trim();
245|    const searchOr: Prisma.BaseUserWhereInput[] = [
246|      { username: buildCaseInsensitiveContains(needle, provider) },
247|      { email: buildCaseInsensitiveContains(needle, provider) },
248|      {
249|        profile: {
250|          OR: [
251|            { firstname: buildCaseInsensitiveContains(needle, provider) },
