255|            { nickname: buildCaseInsensitiveContains(needle, provider) },
256|            { nationalCode: buildCaseInsensitiveContains(needle, provider) },
257|          ],
258|        },
259|      },
260|    ];
261|    if (/^\d+$/.test(needle)) {
262|      searchOr.push({ id: toUserId(Number(needle)) });
263|    }
264|    and.push({ OR: searchOr });
265|  }
266|
267|  if (query.locked === 'true') {
268|    and.push({ locked: { not: 0 } });
269|  } else if (query.locked === 'false') {
270|    and.push({ locked: 0 });
271|  }
272|
273|  if (query.createdFrom?.trim()) {
274|    and.push({ createdAt: { gte: parseDateStart(query.createdFrom) } });
275|  }
276|  if (query.createdTo?.trim()) {
277|    and.push({ createdAt: { lte: parseDateEnd(query.createdTo) } });
278|  }
279|  if (query.updatedFrom?.trim()) {
280|    and.push({ updatedAt: { gte: parseDateStart(query.updatedFrom) } });
281|  }
282|  if (query.updatedTo?.trim()) {
283|    and.push({ updatedAt: { lte: parseDateEnd(query.updatedTo) } });
284|  }
285|
286|  return and.length > 0 ? { AND: and } : {};
